eval("{// Module\nvar code = `\n\n<!-- ko if: state === 'details' -->\n\n<!-- ko ifnot: loading() -->\n<div class=\"etl-module-component-container\">\n    <div class=\"etl-module-body\">\n        <h2>\n            <span data-bind=\"text: \\$root.translations.exportTileExcel\"></span>\n        </h2>\n        <section class=\"etl-module-component\">\n            <div class=\"etl-module-component-block\">\n                <h3>\n                    <label for=\"search-url-input\" data-bind=\"text: \\$root.translations.useSearchUrlOptional\"></label>\n                </h3>\n                <textarea id=\"search-url-input\" style=\"min-height: 100px; width: 80%;\" class=\"form-control textarea textarea-resizable\" spellcheck=\"false\" data-bind=\"textInput: searchUrl\"></textarea>\n            </div>\n            <div class=\"etl-module-component-block\">\n                <h3>\n                    <label for=\"resource-model-select\" data-bind=\"text: \\$root.translations.selectAResourceModel\"></label>\n                </h3>\n                <select id=\"resource-model-select\" data-bind=\"\n                    value: selectedGraph,\n                    options: graphs,\n                    optionsText: 'name',\n                    optionsValue: 'graphid',\n                    optionsCaption: \\$root.translations.select,\n                    valueAllowUnset: true,\n                    chosen: {width: '500px'}\"></select>\n\n                <div style=\"display: flex; padding-top: 20px; font-size: 15px;\">\n                    <label for=\"export-concepts-as-uuids\" data-bind=\"text: \\$root.translations.exportConceptsAs\"></label>\n                    <div id=\"export-concepts-as-uuids\" style=\"padding-left: 10px;\">\n                        <div><input style=\"margin-right: 4px; cursor: pointer;\" type=\"radio\" value=\"uuids\" data-bind=\"checked: \\$data.exportConceptsAs\">UUIDs</div>\n                        <div><input style=\"margin-right: 4px; cursor: pointer;\" type=\"radio\" value=\"labels\" data-bind=\"checked: \\$data.exportConceptsAs\">Labels</div>\n                    </div>\n                </div>\n                \n                <div style=\"padding-top: 16px;\">\n                    <h3>\n                        <label for=\"export-file-name\" data-bind=\"text: \\$root.translations.chooseNameForFile\"></label>\n                    </h3>\n                    <input type=\"text\" id=\"export-file-name\" size=\"69\" style=\"border: 1px solid #ddd; padding: 4px; border-radius: 2px;\" data-bind=\"textInput: \\$data.filename\">\n                </div>\n            </div>\n        </section>\n    </div>\n    <div class=\"tabbed-workflow-footer, etl-module-footer\">\n        <button class=\"btn btn-success\" style=\"margin-right: 8px;\" data-bind=\"click: exportResources, css: {disabled: !selectedGraph()}\">\n            <span data-bind=\"text: \\$root.translations.start\"></span>\n        </button>\n    </div>\n</div>\n<!-- /ko -->\n\n<!-- /ko -->\n\n<!-- ko if: state === 'status' -->\n\n<div class=\"branch-csv-etl\" style=\"display: grid; row-gap: 2px; height:fit-content; margin-top: -5px;\">\n    <h4 class=\"summary-title\" style=\"padding-bottom: 20px;\">\n        <span data-bind=\"text: \\$root.translations.exportTileExcelSummary\"></span>\n    </h4>\n    <!-- ko if: ko.unwrap(loadDetails) -->\n    <div class=\"branch-csv-etl-load-summmary\">\n        <!-- ko ifnot: ['failed','indexed'].includes(selectedLoadEvent().status) -->\n        <!-- ko if: loadDetails.graph && !loadDetails.number_of_resources -->\n        <div class=\"etl-loading-metadata-value\">\n            <span data-bind=\"text: loadDetails.graph + ' ' + \\$root.translations.isBeingPrepared\"></span>\n            <i class=\"fa fa-spin fa-spinner\"></i>    \n        </div>\n        <!-- /ko -->\n        <!-- ko if: loadDetails.number_of_resources -->\n        <div class=\"etl-loading-metadata-value\">\n            <span data-bind=\"text: loadDetails.number_of_resources + ' ' + loadDetails.graph + ' ' + \\$root.translations.resourcesAreBeingExported\"></span>\n            <i class=\"fa fa-spin fa-spinner\"></i>\n        </div>\n        <!-- /ko -->\n        <!-- /ko -->\n\n        <!-- ko if: loadDetails.zipfile -->\n        <div class=\"summary-header\">\n            <span data-bind=\"text: \\$root.translations.downloadExportedZipFile\"></span>\n        </div>\n        <div class=\"summary-contents\" style=\"padding-bottom: 20px;\">\n            <div class=\"etl-loading-metadata-value\">\n                <a class=\"file-listing-link\" style=\"color: blue;\" download data-bind=\"text: loadDetails.zipfile.name, attr: { href: '/temp_file/'+loadDetails.zipfile.fileid }\"></a>\n            </div>\n        </div>\n\n        <!-- ko if: loadDetails.skipped_files.length > 0 -->\n        <div class=\"summary-header\">\n            <span data-bind=\"text: \\$root.translations.downloadAdditionalFiles\"></span>\n        </div>\n        <div class=\"summary-contents\" style=\"padding-bottom: 20px;\">\n            <!-- ko foreach: { data: loadDetails.skipped_files, as: 'file' } -->\n            <div class=\"etl-loading-metadata-value\">\n                <a class=\"file-listing-link\" style=\"color: blue;\" data-bind=\"text: file.name, attr: { download: file.name, href: file.url }\"></a>\n            </div>\n            <!-- /ko -->\n        </div>\n        <!-- /ko -->\n\n        <!-- ko if: loadDetails.files_not_found.length > 0 -->\n        <div class=\"summary-header\">\n            <span>These files were not found and could not be exported</span>\n        </div>\n        <div class=\"summary-contents\" style=\"padding-bottom: 20px;\">\n            <!-- ko foreach: { data: loadDetails.files_not_found, as: 'file' } -->\n            <div class=\"etl-loading-metadata-value\">\n                <a class=\"file-listing-link\" data-bind=\"text: file.name\"></a>\n            </div>\n            <!-- /ko -->\n        </div>\n        <!-- /ko -->\n\n        <div class=\"summary-header\">\n            <span data-bind=\"text: \\$root.translations.exportDetails\"></span>\n        </div>\n        <div class=\"summary-contents\">\n            <span class=\"etl-loading-metadata-key\" data-bind=\"text: \\$root.translations.resourceModel + ':'\"></span>\n            <span class=\"etl-loading-metadata-value\" data-bind=\"text: loadDetails.graph\"></span>\n        </div>\n        <div class=\"summary-contents\">\n            <span class=\"etl-loading-metadata-key\" data-bind=\"text: \\$root.translations.numberOfResourcesExported + ':'\"></span>\n            <span class=\"etl-loading-metadata-value\" data-bind=\"text: loadDetails.number_of_resources\"></span>\n        </div>\n        <div class=\"summary-contents\">\n            <span class=\"etl-loading-metadata-key\" data-bind=\"text: \\$root.translations.numberOfRelatedFiles + ':'\"></span>\n            <span class=\"etl-loading-metadata-value\" data-bind=\"text: loadDetails.number_of_files + loadDetails.skipped_files.length\"></span>\n        </div>\n        <div class=\"summary-contents\">\n            <span class=\"etl-loading-metadata-key\" data-bind=\"text: \\$root.translations.numberOfRelatedFilesInZip + ':'\"></span>\n            <span class=\"etl-loading-metadata-value\" data-bind=\"text: loadDetails.number_of_files\"></span>\n        </div>\n        <!-- /ko-->\n    </div>\n    <!-- /ko-->\n</div>\n\n\n\n<div class=\"bulk-load-status\">\n    <h4 class=\"summary-header\">\n        <span data-bind=\"text: \\$root.translations.loadingData\"></span>\n    </h4>\n    <div>\n        <span class=\"etl-loading-metadata-key\" data-bind=\"text: \\$root.translations.loadingStatus + ':'\"></span>\n        <span class=\"etl-loading-metadata-value\" data-bind=\"\n            text:\n                selectedLoadEvent().status == 'indexed' ? \\$root.translations.completed\n                : selectedLoadEvent().status == 'completed' ? \\$root.translations.indexing\n                : selectedLoadEvent().status == 'validated' ? \\$root.translations.running\n                : selectedLoadEvent().status == 'running' ? \\$root.translations.validating\n                : selectedLoadEvent().status == 'reversing' ? \\$root.translations.unloading\n                : selectedLoadEvent().status == 'unloaded' ? \\$root.translations.unloaded\n                : selectedLoadEvent().status == 'cancelled' ? \\$root.translations.cancelled\n                : \\$root.translations.failed\n        \"></span>  \n    </div>\n    <div style=\"padding-top: 10px;\">\n        <span class=\"etl-loading-metadata-key\" data-bind=\"text: \\$root.translations.loadingStarted + ':'\"></span>\n        <span class=\"etl-loading-metadata-value\" data-bind=\"text: formatTime(selectedLoadEvent().load_start_time)\"></span>    \n    </div>\n    <div data-bind=\"if: selectedLoadEvent().load_end_time\">\n        <span class=\"etl-loading-metadata-key\" data-bind=\"text: \\$root.translations.loadingEnded + ':'\"></span>\n        <span class=\"etl-loading-metadata-value\" data-bind=\"text: formatTime(selectedLoadEvent().load_end_time)\"></span>    \n    </div>\n    <div data-bind=\"if: selectedLoadEvent().load_end_time\">\n        <span class=\"etl-loading-metadata-key\" data-bind=\"text: \\$root.translations.loadDuration + ':'\"></span>\n        <span class=\"etl-loading-metadata-value\" data-bind=\"text: timeDifference(selectedLoadEvent().load_end_time, selectedLoadEvent().load_start_time)\"></span>    \n    </div>\n    <div style=\"padding-top: 10px;\" data-bind=\"if: selectedLoadEvent().indexed_time\">\n        <span class=\"etl-loading-metadata-key\" data-bind=\"text: \\$root.translations.indexingEnded + ':'\"></span>\n        <span class=\"etl-loading-metadata-value\" data-bind=\"text: formatTime(selectedLoadEvent().indexed_time)\"></span>    \n    </div>\n    <div data-bind=\"if: selectedLoadEvent().indexed_time\">\n        <span class=\"etl-loading-metadata-key\" data-bind=\"text: \\$root.translations.indexingDuration + ':'\"></span>\n        <span class=\"etl-loading-metadata-value\" data-bind=\"text: timeDifference(selectedLoadEvent().indexed_time, selectedLoadEvent().load_end_time)\"></span>    \n    </div>\n</div>\n\n<!-- ko if: loadDetails.number_of_import -->\n<div class=\"bulk-load-status\" style=\"padding: 5px 0\">\n    <h4 class=\"summary-header\">\n        <span data-bind=\"text: \\$root.translations.importedData\"></span>\n        <span>\n            <a class=\"etl-status-link\" target=\"_blank\" data-bind=\"text: '('+\\$root.translations.viewInEditLog+')', attr: { href: editHistoryUrl }\">\n            </a>\n        </span>\n    </h4>\n    <div>\n        <!-- ko foreach: loadDetails.number_of_import -->\n        <span class=\"etl-loading-metadata-key\" data-bind=\"text: \\$data.name + ' ' + \\$root.translations.instances + ':'\"></span>\n        <span class=\"etl-loading-metadata-value\" data-bind=\"text: \\$data.total\"></span>\n        <!-- ko foreach: \\$data.tiles -->\n        <div style=\"padding-left: 20px;\">\n            <span class=\"etl-loading-metadata-key\" data-bind=\"text: \\$data.tile + ':'\"></span>\n            <span class=\"etl-loading-metadata-value\" data-bind=\"text: \\$data.count\"></span>\n        </div>\n        <!-- /ko -->\n        <!-- /ko -->\n    </div>\n</div>\n<!-- /ko -->\n\n\n\n\n<!-- /ko -->\n`;\n// Exports\nmodule.exports = code;\n\n//# sourceURL=webpack://afs_plocal/../../opt/venv/lib/python3.13/site-packages/arches/app/templates/views/components/etl_modules/tile-excel-exporter.htm?\n}");

