eval("{// Module\nvar code = `\n\n\n<!-- ko if: !configForm  && state === 'form' -->\n\n<div class=\"row widget-wrapper\" data-bind=\"class: nodeCssClasses\">\n    <div class=\"form-group\">\n        <label class=\"control-label widget-input-label\" data-bind=\"text:label\">\n        </label>\n        <!-- ko if: node -->\n        <i data-bind=\"css: {'ion-asterisk widget-label-required': node.isrequired}\"></i>\n        <!-- /ko -->\n        <div class=\"col-xs-12 resource-instance-wrapper\">\n            <select style=\"width:30%; display:inline-block;\" data-bind=\" select2Query: {\n                    select2Config: select2Config\n                }\n            \"></select>\n\n        </div>\n    </div>\n</div>\n\n<!-- /ko -->\n\n<!-- ko if: !configForm  && state === 'report' -->\n<!-- ko if: !ko.unwrap(hideEmptyNodes) || ko.unwrap(hideEmptyNodes) === true && displayValue() -->\n\n<dt data-bind=\"text: label, class: nodeCssClasses\"></dt>\n<dd data-bind=\"class: nodeCssClasses\">\n    <!-- ko if: displayValue -->\n    <a data-bind=\"attr: { href: '#' + value() }, text: displayValue\"></a>\n    <!-- /ko -->\n    <!-- ko ifnot: displayValue -->\n    <span data-bind=\"text: \\$root.translations.none\"></span>\n    <!-- /ko -->\n</dd>\n\n<!-- /ko -->\n<!-- /ko -->\n\n<!-- ko if: !configForm  && state === 'display_value' -->\n\n<span data-bind=\"text: displayValue() || \\$root.translations.none,\n    class: nodeCssClasses\"></span>\n\n<!-- /ko -->\n\n<!-- ko if: configForm -->\n\n<div>\n    <div class=\"control-label\">\n        <span data-bind=\"text: \\$root.translations.placeholder\"></span>\n    </div>\n    <div class=\"col-xs-12 pad-no crud-widget-container\">\n        <div class=\"node-config-item\">\n        <input class=\"form-control input-md widget-input\" data-bind=\"\n                attr: {placeholder: \\$root.translations.placeholder},\n                value: placeholder,\n                valueUpdate: 'keyup'\n            \">\n        </div>\n        <div class=\"node-config-item\">\n        <div class=\"control-label\">\n            <span data-bind=\"text: \\$root.translations.dropdownFormat\"></span>\n        </div>\n        <div class=\"toggle-container\">\n            <span class=\"switch switch-small\" data-bind=\"css: {'on': displayOnlySelectedNode()}, click: toggleDisplayOnlySelected\"><small></small></span>\n                    <div style=\"display:flex; flex-direction:row;\">\n                    <div class=\"arches-toggle-sm\" data-bind=\"text:\\$root.translations.showOnlySelectedNodeInDropdown\"></div>\n                    </div>\n            <span class=\"arches-toggle-subtitle\" data-bind=\"text:\\$root.translations.limitDropdownToWidgetNodes\"></span>\n        </div>\n        </div>\n    </div>\n</div>\n\n<!-- /ko -->\n`;\n// Exports\nmodule.exports = code;\n\n//# sourceURL=webpack://afs_plocal/../../opt/venv/lib/python3.13/site-packages/arches/app/templates/views/components/widgets/node-value-select.htm?\n}");

