eval("{// Module\nvar code = `\n<!-- ko if: !\\$data.configForm -->\n<!-- ko if: !\\$data.summary -->\n\n    \n    <!-- Custom Template Report Title Bar -->\n    <div class=\"relative\">\n\n        <!-- Title Block -->\n        <div class=\"afs-report-toolbar\">\n            <h1 class=\"afs-report-toolbar-title\"><span class=\"afs-report-name\">Digital Resource:</span><span data-bind=\"text: displayname\" class=\"afs-report-instance-name\"></span></h1>\n        </div>\n\n    </div>\n    \n\n    \n    \n    <!-- Link nav -->\n    <div class=\"afs-report-anchor-container\">\n        <ol class=\"afs-report-anchors breadcrumb\">\n            <!-- ko foreach: {data: sections, as: 'section'} -->\n            <li data-bind=\"click: function(){\\$parent.activeSection(section.id)}, css: {active: \\$parent.activeSection() === section.id}, text: section.title\" class=\"afs-report-a\"></li>\n            <!-- /ko -->\n        </ol>\n    </div>\n    <div class=\"afs-tabbed-report\">\n        <div class=\"afs-tabbed-report-content\">\n            <!-- Names Tab -->\n            <div class=\"afs-report-page\" data-bind=\"if: activeSection() === 'name'\">\n                <div data-bind=\"component: {\n                    name: 'views/components/reports/scenes/name',\n                    params: {\n                        data: resource,\n                        cards: nameCards,\n                        dataConfig: nameDataConfig\n                    }\n                }\"></div>\n            </div>\n            <!-- Description Tab -->\n            <div class=\"afs-report-page\" data-bind=\"if: activeSection() === 'description'\">\n                <div data-bind=\"component: {\n                    name: 'views/components/reports/scenes/description',\n                    params: {\n                        data: resource,\n                        cards: descriptionCards,\n\n                    }\n                }\"></div>\n            </div>\n            <!-- Documentation Tab -->\n            <div class=\"afs-report-page\" data-bind=\"if: activeSection() === 'documentation'\">\n                <div data-bind=\"component: {\n                    name: 'views/components/reports/scenes/documentation',\n                    params: {\n                        data: resource,\n                        cards: documentationCards,\n                        dataConfig: documentationDataConfig\n\n                    }\n                }\"></div>\n            </div>\n            <!-- Existence Tab -->\n            <div class=\"afs-report-page\" data-bind=\"if: activeSection() === 'existence'\">\n                <div data-bind=\"component: {\n                    name: 'views/components/reports/scenes/existence',\n                    params: {\n                        data: resource,\n                        cards: existenceCards,\n                        events: existenceEvents,\n                        dataConfig: existenceDataConfig,\n                    }\n                }\"></div>\n            </div>           \n             <!-- Events Tab -->\n            <div class=\"afs-report-page\" data-bind=\"if: activeSection() === 'events'\">\n                <div data-bind=\"component: {\n                    name: 'views/components/reports/scenes/existence',\n                    params: {\n                        data: resource,\n                        cards: eventsCards,\n                        events: eventsEvents,\n                        dataConfig: eventsDataConfig,\n                    }\n                }\"></div>\n            </div>\n            <!-- Information Carriers Tab -->\n            <div data-bind=\"if: activeSection() === 'carriers'\">\n                <div class=\"afs-report-section\">\n                    <h2 class=\"afs-report-section-title\"><i data-bind=\"click: function() {toggleVisibility(visible.carriers)}, css: {'fa-angle-double-right': visible.files(), 'fa-angle-double-up': !visible.files()}, attr: {'aria-label': 'Expand/Collapse'}\" class=\"fa toggle\"></i> Files</h2>\n                    <span data-bind=\"if: cards[cardIds.filesOfDigitalResource] && (!files().length || cards[cardIds.filesOfDigitalResource].cardinality == 'n')\">\n                        <a class=\"afs-report-a\" data-bind=\"click: function(){addNewTile(cards[cardIds.filesOfDigitalResource])}\"><i class=\"fa fa-mail-reply\" aria-hidden=\"true\"></i> Add File</a>\n                    </span>\n                \n                    <!-- Collapsible content -->\n                    <div data-bind=\"visible: visible.files\" class=\"afs-report-collapsible-container pad-lft\">\n                \n                        <!-- ko ifnot: files().length -->\n                        <div class=\"afs-nodata-note\">No names for this resource</div>\n                        <!-- /ko -->\n                        \n                        <!-- ko if: files().length -->\n                        <div class=\"afs-report-subsection\">\n                            <div>\n                                <div class=\"afs-table pad-btm\">\n                                    <table class=\"table table-striped\" cellspacing=\"0\" width=\"100%\">\n                                        <thead>\n                                            <tr class=\"afs-table-header\">\n                                                <th>Name</th>\n                                                <th class=\"min-tabletl\">Metadata Exists</th>\n                                                <th class=\"afs-table-control all\"></th>\n                                            </tr>\n                                        </thead>\n                                        <tbody data-bind=\"dataTablesForEach: { data: files, dataTableOptions: filesTable }\">\n                                            <tr>\n                                                <td data-bind=\"text: name\"></td>\n                                                <td data-bind=\"text: metadataExists\"></td>\n                                                <td class=\"afs-table-control\">\n                                                    <div data-bind=\"if: \\$parent.cards && \\$parent.cards[\\$parent.cardIds.filesOfDigitalResource]\">\n                                                        <a data-bind=\"click: function() {\\$parent.editTile(tileid, \\$parent.cards[\\$parent.cardIds.filesOfDigitalResource])},\n                                                            attr: {'aria-label': \\$root.translations.edit}\">\n                                                            <i class=\"fa fa-mail-reply\" aria-hidden=\"true\"></i>\n                                                        </a>\n                                                        <a data-bind=\"click: \\$parent.deleteTile.bind(\\$data, tileid, \\$parent.cards[\\$parent.cardIds.filesOfDigitalResource]),\n                                                            attr: {'aria-label': \\$root.translations.delete}\">\n                                                            <i class=\"fa fa-trash\" aria-hidden=\"true\"></i>\n                                                        </a>\n                                                    </div>\n                                                </td>\n                                            </tr>\n                                        </tbody>\n                                    </table>\n                                </div>\n                            </div>\n                        </div>\n                        <!-- /ko -->\n                    </div>\n                </div>\n            </div>\n            <!-- Substance Tab -->\n            <div class=\"afs-report-page\" data-bind=\"if: activeSection() === 'substance'\">\n                <div data-bind=\"component: {\n                    name: 'views/components/reports/scenes/substance',\n                    params: {\n                        data: resource,\n                        cards: substanceCards,\n                        additionalData: additionalData\n                    }\n                }\"></div>\n            </div>\n            <!-- Aboutness Tab -->\n            <div class=\"afs-report-page\" data-bind=\"if: activeSection() === 'aboutness'\">\n                <div data-bind=\"component: {\n                    name: 'views/components/reports/scenes/default',\n                    params: {\n                        data: aboutnessData\n                    }\n                }\"></div>\n            </div>  \n            <!-- Parthood Tab -->\n            <div class=\"afs-report-page\" data-bind=\"if: activeSection() === 'parthood'\">\n                <div data-bind=\"component: {\n                    name: 'views/components/reports/scenes/default',\n                    params: {\n                        data: parthoodData\n                    }\n                }\"></div>\n            </div> \n            <!-- Sethood Tab -->\n            <div class=\"afs-report-page\" data-bind=\"if: activeSection() === 'sethood'\">\n                <div data-bind=\"component: {\n                    name: 'views/components/reports/scenes/default',\n                    params: {\n                        data: sethoodData\n                    }\n                }\"></div>\n            </div>   \n            <!-- JSON Tab -->\n           <div class=\"afs-report-page afs-flex-col\" data-bind=\"if: activeSection() === 'json'\">\n               <div class=\"afs-flex-col\" data-bind=\"component: {\n                   name: 'views/components/reports/scenes/json',\n                   params: {\n                       resourceInstanceId: reportMetadata().resourceinstanceid,\n                   }\n               }\"></div>\n           </div>\n        </div>\n    </div>\n\n                \n\n    \n\n<!-- /ko -->\n\n<!-- ko if: \\$data.summary -->\n\n<div class=\"afs-summary-report-header\">\n    <h1 class=\"afs-summary-report-title\"><span data-bind=\"text: displayname\" class=\"afs-report-instance-name\"></span><span class=\"afs-report-name pad-lft-sm\">(Digital Resource)</span></h1>\n</div>\n<div class=\"model-summary-report\">\n    <div class=\"afs-report-page\">\n        <!-- ko if: \\$data.thumbnail() -->\n            <!-- Image Preview -->\n            <div class=\"afs-report-section\">\n                <h2 class=\"afs-report-section-title\">Digital Resource Image Preview</h2>\n                <div style=\"padding-top: 10px; padding-left: 10px;\">\n                    <img style=\"border: 1px solid #343434;\" data-bind=\"attr:{src: thumbnail()}\">\n                </div>\n            </div>\n        <!-- /ko -->\n\n        <!-- Names -->\n        <div class=\"afs-report-section\">\n            <h2 class=\"afs-report-section-title\">Digital Resource Name</h2>\n            <div class=\"afs-report-subsection\">\n                <!-- ko ifnot: nameSummary() && nameSummary().length -->\n                <h3 class=\"afs-report-nodata-message\">There is no name for this resource</h3>\n                <!-- /ko -->\n\n                <!-- ko if: nameSummary() && nameSummary().length -->\n                <div class=\"afs-table pad-btm\">\n                    <table class=\"table table-striped\" cellspacing=\"0\" width=\"100%\">\n                        <thead>\n                            <tr class=\"afs-table-header\">\n                                <th>Name</th>\n                                <th>Name Type</th>\n                            </tr>\n                        </thead>\n                        <tbody data-bind=\"dataTablesForEach: { data: nameSummary, dataTableOptions: getTableConfig(2) }\">\n                            <tr>\n                                <td data-bind=\"text: content\"></td>\n                                <td data-bind=\"text: type\"></td>\n                            </tr>\n                        </tbody>\n                    </table>\n                </div>\n                <!-- /ko -->\n            </div>\n        </div>\n\n        <!-- Statements -->\n        <div class=\"afs-report-section\">\n            <h2 class=\"afs-report-section-title\">Statements</h2>\n            <div class=\"afs-report-subsection\">\n                <!-- ko ifnot: statementsSummary() && statementsSummary().length -->\n                <h3 class=\"afs-report-nodata-message\">There are no statements for this resource</h3>\n                <!-- /ko -->\n\n                <!-- ko if: statementsSummary() && statementsSummary().length -->\n                <div class=\"afs-table pad-btm\">\n                    <table class=\"table table-striped\" cellspacing=\"0\" width=\"100%\">\n                        <thead>\n                            <tr class=\"afs-table-header\">\n                                <th>Statements</th>\n                                <th>Type</th>\n                            </tr>\n                        </thead>\n                        <tbody data-bind=\"dataTablesForEach: { data: statementsSummary, dataTableOptions: getTableConfig(2) }\">\n                            <tr>\n                                <td id=\"project-search-statement-content\" data-bind=\"text: content\"></td>\n                                <td data-bind=\"text: type\"></td>\n                            </tr>\n                        </tbody>\n                    </table>\n                </div>\n                <!-- /ko -->\n            </div>\n        </div>\n    </div>\n</div>\n\n\n<!-- /ko -->\n<!-- end of not configForm -->\n<!-- /ko -->\n\n\n<!-- ko if: \\$data.configForm && (\\$data.configType === 'header') -->\n\n\n<!-- /ko -->\n`;\n// Exports\nmodule.exports = code;\n\n//# sourceURL=webpack://afs_plocal/../arches-for-science/arches_for_science/templates/views/components/reports/digital-resource.htm?\n}");

