eval("{// Module\nvar code = `\n<!-- ko if: !\\$data.configForm -->\n<!-- ko if: !\\$data.summary -->\n\n\n\n<!-- ko if: dataConfig.dimension -->\n<div class=\"afs-report-section\">\n    <h2 class=\"afs-report-section-title\"><i data-bind=\"click: function() {toggleVisibility(visible.dimensions)}, css: {'fa-angle-double-right': visible.dimensions(), 'fa-angle-double-up': !visible.dimensions()}, attr: {'aria-label': 'Expand/Collapse'}\" class=\"fa toggle\"></i> Dimensions</h2>\n    <span data-bind=\"if: cards.dimension\">\n        <a class=\"afs-report-a\" data-bind=\"click: function(){add(cards.dimension)}\"><i class=\"fa fa-mail-reply\" aria-hidden=\"true\"></i> Add Dimension</a>\n    </span>\n\n    <!-- Collapsible content -->\n    <div data-bind=\"visible: visible.dimensions\" class=\"afs-report-collapsible-container pad-lft\">\n\n        <!-- ko ifnot: dimensions().length -->\n        <div class=\"afs-nodata-note\">No dimensions for this resource</div>\n        <!-- /ko -->\n        \n        <!-- ko if: dimensions().length -->\n        <div class=\"afs-report-subsection\">\n            <div class=\"firstchild-container\">\n                <div class=\"afs-table pad-btm\">\n                    <table class=\"table table-striped\" cellspacing=\"0\" width=\"100%\">\n                        <thead>\n                            <tr class=\"afs-table-header\">\n                                <th>Type</th>\n                                <th class=\"min-tabletl\">Unit</th>\n                                <th class=\"min-medium\">Value</th>\n                                <th class=\"none\">Highest Possible Value</th>\n                                <th class=\"none\">Lowest Possible Value</th>\n                                <th class=\"afs-table-control all\"></th>\n                            </tr>\n                        </thead>\n                        <tbody data-bind=\"dataTablesForEach: { data: dimensions, dataTableOptions: dimensionTableConfig }\">\n                            <tr>\n                                <td data-bind=\"text: type\"></td>\n                                <td data-bind=\"text: unit\"></td>\n                                <td data-bind=\"text: dimensionValue\"></td>\n                                <td data-bind=\"text: highestValue\"></td>\n                                <td data-bind=\"text: lowestValue\"></td>\n                                <td class=\"afs-table-control\">\n                                    <div data-bind=\"if: \\$parent.cards && \\$parent.cards.dimension\">\n                                        <a data-bind=\"click: function() {\\$parent.edit(tileid, \\$parent.cards.dimension)},\n                                            attr: {'aria-label': \\$root.translations.edit}\">\n                                            <i class=\"fa fa-mail-reply\" aria-hidden=\"true\"></i>\n                                        </a>\n                                        <a data-bind=\"click: \\$parent.delete.bind(\\$data, tileid, \\$parent.cards.dimension),\n                                            attr: {'aria-label': \\$root.translations.delete}\">\n                                            <i class=\"fa fa-trash\" aria-hidden=\"true\"></i>\n                                        </a>\n                                    </div>\n                                </td>\n                            </tr>\n                        </tbody>\n                    </table>\n                </div>\n            </div>\n        </div>\n        <!-- /ko -->\n    </div>\n</div><span></span>\n<div data-bind=\"if: additionalData\" class=\"afs-report-section\">\n    <h2 class=\"afs-report-section-title\"><i data-bind=\"click: function() {toggleVisibility(visible.additionalData)}, css: {'fa-angle-double-right': visible.additionalData(), 'fa-angle-double-up': !visible.additionalData()}, attr: {'aria-label': 'Expand/Collapse'}\" class=\"fa toggle\"></i> Additional Data</h2>\n    <span data-bind=\"if: cards.material\">\n        <a class=\"afs-report-a\" data-bind=\"click: function(){add(cards.material)}\"><i class=\"fa fa-mail-reply\" aria-hidden=\"true\"></i> Add Material</a>\n    </span>\n\n    <!-- Collapsible content -->\n    <div data-bind=\"visible: visible.additionalData\" class=\"afs-report-collapsible-container pad-lft\">\n\n        <!-- ko ifnot: additionalData().length -->\n        <div class=\"afs-nodata-note\">No material for this resource</div>\n        <!-- /ko -->\n        \n        <!-- ko if: additionalData().length -->\n        <div class=\"afs-report-subsection\">\n            <div>\n                <div data-bind=\"foreach: {data: additionalData, as: 'item', noChildContext: true}\" class=\"afs-report-subsection-ite\">\n                    <div class=\"afs-block-attributes pad-btm\">\n                        <div class=\"afs-keyvalue\" data-bind=\"component: {\n                            name: 'views/components/reports/scenes/keyvalue',\n                            params: {\n                                data: item,\n                                inline: true\n                            }\n                        }\"></div>\n                    </div>\n                </div>\n            </div>\n        </div>\n        <!-- /ko -->\n    </div>\n</div>\n<!-- /ko -->\n<!-- ko if: dataConfig.timespan -->\n<div data-bind=\"component: {\n    name: 'views/components/reports/scenes/default',\n    params: {\n        data: timeSpanData,\n    }\n}\"></div>\n<!-- /ko -->\n\n\n<!-- /ko -->\n\n<!-- ko if: \\$data.summary -->\n\n<div class=\"relative report-title-bar\">\n\n    <!-- Title Block -->\n    <div class=\"report-toolbar-preview ep-form-toolbar\">\n        <h4 class=\"report-toolbar-title\"><span data-bind=\"text: report.get('name')\"></span> - <span data-bind=\"text: report.get('displayname') \"></span></h4>\n\n        <!-- Tools -->\n        <div class=\"ep-form-toolbar-tools mar-no flex\">\n            <p class=\"report-print-date\">\n                <span data-bind=\"text: \\$root.translations.reportDate\"></span>\n                <span data-bind=\"text: reportDate\"></span>\n            </p>\n        </div>\n    </div>\n</div>\n\n<div class=\"rp-report-container-preview\">\n    <div class=\"rp-report-section relative rp-report-section-root\">\n        <div class=\"rp-report-section-title\">\n            <!-- ko if: report.cards.length > 0 -->\n                <!--ko let: { card: report.cards[0] }-->\n                <div class=\"rp-card-section\">\n                    <!-- ko component: {\n                        name: card.model.cardComponentLookup[card.model.component_id()].componentname,\n                        params: {\n                        state: 'report',\n                        preview: report.preview,\n                        card: card,\n                        pageVm: \\$root\n                    }\n                    } --> <!-- /ko -->\n                </div>\n                <!--/ko-->\n            <!-- /ko -->\n        </div>\n    </div>\n</div>\n\n<!-- /ko -->\n<!-- end of not configForm -->\n<!-- /ko -->\n\n\n<!-- ko if: \\$data.configForm && (\\$data.configType === 'header') -->\n\n\n<!-- /ko -->\n`;\n// Exports\nmodule.exports = code;\n\n//# sourceURL=webpack://afs_plocal/../arches-for-science/arches_for_science/templates/views/components/reports/scenes/substance.htm?\n}");

