eval("{// Module\nvar code = `\n\n\n<div class=\"loading-mask\" data-bind=\"visible: loading\"></div>\n<div class=\"afs-saving-message\" data-bind=\"visible: loading, text: loadingMessage()\"></div>\n<!-- ko with: \\$data, as: 'self' -->\n    \n<div class=\"workbench-card-wrapper\" data-bind=\"class: ko.unwrap(\\$data.workbenchWrapperClass)\">\n    <!-- ko if: showTabs -->\n    <div class=\"workbench-card-sidebar\">\n        \n<div class=\"workbench-card-sidebar-tab\" data-bind=\"click: function() {\n    toggleTab('dataset');\n}, css: {\n    'active': activeTab() === 'dataset'\n}\">\n    <i class=\"fa fa-book\" aria-hidden=\"true\"></i>\n    <span class=\"map-sidebar-text\">Dataset</span>\n</div>\n\n<div class=\"workbench-card-sidebar-tab\" data-bind=\"click: function() {\n    toggleTab('imageTools');\n}, css: {\n    'active': activeTab() === 'imageTools',\n    'disabled': !canvas() || expandGallery()\n}\">\n    <i class=\"fa fa-image\"></i>\n    <span data-bind=\"text: \\$root.translations.image\" class=\"map-sidebar-text\"></span>\n</div>\n<div class=\"workbench-card-sidebar-tab\" data-bind=\"click: function() {\n    toggleTab('annotations');\n}, css: {\n    'active': activeTab() === 'annotations',\n    'disabled': !canvas() || expandGallery()\n}\">\n    <i class=\"fa fa-list\"></i>\n    <span data-bind=\"text: \\$root.translations.overlays\" class=\"map-sidebar-text\"></span>\n</div>\n\n\n    </div>\n    <!-- /ko -->\n    <!--ko if: activeTab() -->\n    <div class=\"workbench-card-sidepanel\" data-bind=\"css:{'expanded': expandSidePanel()}\">\n        \n<!--ko foreach: { data: [\\$data], as: 'self' }-->\n<!--ko if: activeTab() === 'dataset'-->\n<div class=\"workbench-card-sidepanel-header-container\">\n    <h4 class=\"workbench-card-sidepanel-header\" data-bind=\"click: hideSidePanel\">Manage Dataset</h4>\n</div>\n<div class=\"workbench-card-sidepanel-border\"></div>\n<div class=\"workbench-card-sidepanel-body\">\n\n    <!-- endif -->\n\n    <div class=\"iiif-image-tools upload-dataset-select-dataset-files\">\n        <!--ko if: annotations().length > 0-->\n        <div style=\"width:100%; display: flex;\">\n            <button class=\"btn\" style=\"background: #9490EE;color: #fff;\" data-bind=\"visible: self.showDatasetDetails, click: function(){self.showDatasetDetails(false)}\">\n                <i class=\"fa fa-list\" aria-hidden=\"true\" style=\"color: #fff\"></i> Back to Sampled Area List</button>\n        </div>\n\n        <div data-bind=\"visible: !self.showDatasetDetails()\">\n            <label class=\"control-label\" style=\"font-size: 1.2em; font-weight: 500;\">Sampled Locations</label>\n            <div style=\"margin-bottom: 10px; border: 1px solid #9951C0; padding: 20px; background-color: #FFFF00; border-radius: 2px;\">\n                <div style=\"font-size: 1.15em; text-align: center; color: #440468;\">\n                    <i class=\"fa fa-info-circle\" aria-hidden=\"true\"></i><span style=\"margin-left: 5px;\">Select a Location or Area</span>\n                </div>\n                <div style=\"color: #9951C0; text-align: center;\"> Click on a location or area from the list below to start uploading files. Locked locations/areas were uploaded by others and can't be edited</div>\n            </div>\n            <input type=\"text\" class=\"form-control\" style=\"width: 100%;\" data-bind=\"textInput: partFilter, attr: {'placeholder': \\$root.translations.filter}\">\n        </div>\n        <div class=\"panel\" style=\"margin-bottom: 0px;\">\n            <div style=\"margin-top: 5px\">\n                <div data-bind=\"visible: !self.showDatasetDetails()\">\n                    <div id=\"parts-panel\" data-bind=\"foreach: {data: parts, as: 'part'}\">\n                        <!--ko if: self.partFilter() === \"\" || part.displayname.toLowerCase().includes(self.partFilter().toLowerCase()) -->\n                        <div class=\"panel\">\n                            <a role=\"button\" data-parent=\"#parts-panel\" aria-expanded=\"false\" data-bind=\"click: function(){ \\$parent.showDatasetDetails(true); \\$parent.selectedPart(part); }, attr: { href: '#' + part.tileid, 'aria-expanded': \\$index == 0 ? 'true' : 'false' }\">\n                                <div style=\"height: 25px; padding: 10px; display: flex; align-items:center;\" class=\"file-workbench-file\">\n                                    <span style=\"flex: 1\" class=\"file-name manifest-manager-canvas-name\" data-bind=\"text: part.displayname + ' (' + part.type + ')'\"></span>\n\n                                    <div data-bind=\"visible: part.datasetId()\">\n                                        (<span data-bind=\"text: ko.unwrap(part?.datasetFiles)?.length\"></span> <span data-bind=\"visible: ko.unwrap(part?.datasetFiles)?.length === 1\">new file</span><span data-bind=\"visible: ko.unwrap(part?.datasetFiles)?.length !== 1\">new files</span>)\n                                    </div>\n                                </div>\n  \n                            </a>\n                            \n                        </div>\n                        <!--/ko-->\n                    </div>\n                </div>\n\n                <div data-bind=\"visible: self.showDatasetDetails\">\n                    <div style=\"margin-bottom: 10px; border: 1px solid #9951C0; padding: 20px; background-color: #FFFF00; border-radius: 2px;\">\n                        <div style=\"font-size: 1.15em; text-align: center; color: #440468;\">\n                            <i class=\"fa fa-info-circle\" aria-hidden=\"true\"></i><span style=\"margin-left: 5px;\">File Formats</span>\n                        </div>\n                        <div style=\"color: #9951C0; text-align: center;\">Only ASCII files can be presented as interactive charts. Supported image files and PDF files will be automatically detected and displayed.</div>\n                    </div>\n                    <div style=\"margin-top: 15px;\" data-bind=\"visible: selectedPartHasCurrentObservation()\">\n                        <div class=\"dataset-name\">\n                            <label class=\"control-label\" style=\"font-size: 1.2em; font-weight: 500;\">Dataset Name</label>\n                            <div style=\"display: flex\">\n                                <input style=\"flex: 1;\" type=\"text\" class=\"form-control\" placeholder=\"Dataset Name\" data-bind=\"enable: self.selectedPartHasCurrentObservation(), textInput: selectedPart().datasetName\">\n                            </div>\n                            <div style=\"display: flex;\">\n                                <input class=\"afs-calculated-datasetname\" style=\"flex: 1; margin-bottom: 0px;\" disabled=\"disabled\" type=\"text\" data-bind=\"textInput: selectedPartHasCurrentObservation() ? selectedPart().calcDatasetName : selectedPart().datasetName\">\n                            </div>\n                        </div>\n                        <!-- ko if: uploadFailed -->\n                        <div style=\"padding: 10px; border: 1px solid #eee;\" class=\"afs-error-message ep-alert-red\">\n                            <i class=\"fa fa-warning\" style=\"margin: 0 6px;\" data-bind=\"attr: {'aria-label': \\$root.translations.warning}\"></i>\n                            Failed to upload files.  Try again or contact an administrator.\n                        </div>\n                        <!-- /ko -->\n                        <div class=\"dropzone-photo-upload\" style=\"height: 80px; padding: 30px 15px; background: #C1F25F; border: 1px dashed #619100; border-radius: 2px; margin-bottom: 10px;\" data-bind=\"visible: selectedPartHasCurrentObservation(), dropzone: dropzoneOptions\">\n                            <div class=\"file-workbench-links\">\n                                <a class=\"upload-dataset-files dz-clickable\" data-bind=\"css: uniqueidClass\">\n                                    <span>Drag or <strong>click here</strong> to upload files</span>\n                                </a>\n                            </div>\n                            <div style=\"min-height: 100%;\">\n                                <div id=\"hidden-dz-previews\" style=\"display:none\"></div>\n                            </div>\n                        </div>\n                    </div>\n                    <div class=\"panel-collapse collapse\" data-bind=\"visible: ko.unwrap(selectedPart().datasetFiles).length; attr: { id: selectedPart().tileid }, css: { in: \\$index() == 0}\">\n                        <label class=\"control-label\" style=\"font-size: 1.2em; font-weight: 500; padding-top: 5px;\">Files in Dataset</label>\n                        <div class=\"file-workbench-files\" style=\"height: 215px;\" data-bind=\"foreach: {data: selectedPart().datasetFiles, as: 'file'}\">\n                            <div class=\"file-workbench-file\" style=\"display: flex;\" data-bind=\"css: {staged: false}\">\n                                <div style=\"flex: 1\">\n                                    <i data-bind=\"\n                                        click: function(){ \\$parent.deleteFile(file)},\n                                        attr: {'aria-label': \\$root.translations.delete}\" class=\"fa fa-trash\" style=\"color: black\"></i>\n                                    <span class=\"file-name manifest-manager-canvas-name\" data-bind=\"text: file.name\"></span>\n                                </div>\n                            </div>\n                        </div>\n                        <div style=\"margin-bottom: 10px;\"><span data-bind=\"text: ko.unwrap(selectedPart().datasetFiles).length\"></span> files</div>\n                    </div>\n                </div>\n            </div>\n        </div>\n        <!--/ko-->\n    </div>\n\n    <div class=\"iiif-image-tools upload-dataset-select-dataset-files\" style=\"margin-top: -20px;\" data-bind=\"if: self.selectedPartHasCurrentObservation()\">\n        <!--ko if: files().length > 0 && selectedPart() -->\n        <label class=\"control-label\">Available Files</label>\n        <div class=\"file-workbench-files\" data-bind=\"foreach: {data: files, as: 'file'}\">\n            <div class=\"file-workbench-file\" data-bind=\"css: {staged: false}\">\n                <i class=\"fa fa-upload\" data-bind=\"value: file, click: function(){\\$parent.addFileToPart(file)}\"></i>\n                <span class=\"file-name manifest-manager-canvas-name\" data-bind=\"text: file.name, click: function(){\\$parent.addFileToPart(file)}, clickBubble: false\"></span>\n            </div>\n        </div>\n        <!--/ko-->\n\n    </div>\n</div>\n\n\n<div class=\"workbench-button-panel\">\n    <button style=\"width: 100%;\" class=\"btn btn-success\" data-bind=\"click: function(){\\$parent.saveFiles(); }, css: {disabled: !(self.showDatasetDetails() && selectedPart()?.nameDirty())}, attr: {disabled: !(self.showDatasetDetails() && selectedPart()?.nameDirty())}\">\n        <i class=\"ion-android-cloud-done\" aria-hidden=\"true\"></i>\n        <span>Save</span>\n    </button>\n</div>\n\n\n<!--/ko-->\n<!--/ko-->\n\n<!--ko if: activeTab() === 'imageTools' -->\n<div class=\"workbench-card-sidepanel-header-container\">\n    <h4 class=\"workbench-card-sidepanel-header\" data-bind=\"\n            text: \\$root.translations.imageTools,\n            click: hideSidePanel\n        \"></h4>\n</div>\n<div class=\"workbench-card-sidepanel-border\"></div>\n<div class=\"workbench-card-sidepanel-body\">\n<div class=\"iiif-image-tools\">\n    <div data-bind=\"if: showModeSelector\" class=\"layout\">\n        <div>\n            <span data-bind=\"text: \\$root.translations.panelLayout\"></span>\n        </div>\n        <div class=\"mode-selector\">\n            <div data-bind=\"click: function(){ compareMode(false); return true; }, css: { selected: !compareMode() }\">\n                <div class=\"selector-button\"></div>\n                <input name=\"panelGroup\" value=\"single\" type=\"radio\" data-bind=\"checked: panelRadio\">\n                <span data-bind=\"text: \\$root.translations.singlePanel\"></span>\n            </div>\n            <div data-bind=\"click: function(){ compareMode(true); return true; }, css: { selected: compareMode() }\">\n                <div>\n                    <div class=\"selector-button\"></div>\n                    <div class=\"selector-button\"></div>\n                </div>\n                <input name=\"panelGroup\" value=\"double\" type=\"radio\" data-bind=\"checked: panelRadio\">\n                <span data-bind=\"text: \\$root.translations.doublePanel\"></span>\n            </div>\n        </div>\n\n        <div class=\"panel-selector\">\n            <span data-bind=\"text: \\$root.translations.selectedPanelLayout\"></span>\n            <div class=\"selector\">\n                <div data-bind=\"css: { selected: selectPrimaryPanel() }\">\n                    <div data-bind=\"click: function(){selectPrimaryPanel(true)}\" class=\"primary\">\n                        <span data-bind=\"text: \\$root.translations.panelOne\"></span>\n                    </div>\n                </div>\n                <div data-bind=\"css: { selected: !selectPrimaryPanel() }, if: compareMode()\">\n                    <div class=\"secondary\" data-bind=\"click: function(){selectPrimaryPanel(false)}\">\n                        <span data-bind=\"text: \\$root.translations.panelTwo\"></span>\n                    </div>\n                </div>\n            </div>\n        </div>\n    </div>\n\n    <div data-bind=\"if: showModeSelector\" style=\"width: 96%; margin: 20px 0px;\">\n        <select class=\"form-control input-lg widget-input\" data-bind=\"\n            select2Query: {\n                select2Config: imageToolConfig\n            }\">\n        </select>\n    </div>\n\n    <div class=\"iiif-image-tool-slider\">\n        <div class=\"iiif-image-tool-label\">\n            <i class=\"fa fa-lightbulb-o\"></i>\n            <span data-bind=\"text: \\$root.translations.brightness\"></span>\n        </div>\n        <div class=\"iiif-image-tool-slider-wrap\">\n            <input type=\"range\" min=\"0\" max=\"200\" step=\"1\" data-bind=\"value: brightness, valueUpdate: 'input'\">\n        </div>\n        <div class=\"iiif-image-tool-value\">\n            <span data-bind=\"text: brightness\"></span>%\n        </div>\n    </div>\n    <div class=\"iiif-image-tool-slider\">\n        <div class=\"iiif-image-tool-label\">\n            <i class=\"fa fa-adjust\"></i>\n            <span data-bind=\"text: \\$root.translations.contrast\"></span>\n        </div>\n        <div class=\"iiif-image-tool-slider-wrap\">\n            <input type=\"range\" min=\"0\" max=\"200\" step=\"1\" data-bind=\"value: contrast, valueUpdate: 'input'\">\n        </div>\n        <div class=\"iiif-image-tool-value\">\n            <span data-bind=\"text: contrast\"></span>%\n        </div>\n    </div>\n    <div class=\"iiif-image-tool-slider\">\n        <div class=\"iiif-image-tool-label\">\n            <i class=\"fa fa-eyedropper\"></i>\n            <span data-bind=\"text: \\$root.translations.saturation\"></span>\n        </div>\n        <div class=\"iiif-image-tool-slider-wrap\">\n            <input type=\"range\" min=\"0\" max=\"200\" step=\"1\" data-bind=\"value: saturation, valueUpdate: 'input'\">\n        </div>\n        <div class=\"iiif-image-tool-value\">\n            <span data-bind=\"text: saturation\"></span>%\n        </div>\n    </div>\n    <div class=\"iiif-image-tool-slider\">\n        <div class=\"iiif-image-tool-label\">\n            <i class=\"fa fa-image\"></i>\n            <span data-bind=\"text: \\$root.translations.greyscale\"></span>\n        </div>\n        <div class=\"toggle-container\">\n            <span class=\"switch switch-small switch-widget\" data-bind=\"css: {'on': greyscale()}, click: function() { greyscale(!greyscale()); }\"><small></small></span>\n            <div style=\"display:flex; flex-direction:row;\">\n                <div class=\"arches-toggle-sm\" data-bind=\"click: function() { greyscale(!greyscale()); }\">\n                    <span data-bind=\"text: \\$root.translations.displayAsGreyscale\"></span>\n                </div>\n            </div>\n        </div>\n    </div>\n\n    <div class=\"install-buttons\">\n        <button class=\"btn btn-shim btn-danger btn-labeled btn-lg fa fa-refresh\" data-bind=\"click: resetImageSettings\">\n            <span data-bind=\"text: \\$root.translations.resetToDefaults\"></span>\n        </button>\n    </div>\n</div>\n</div>\n<!--/ko -->\n<!--ko if: activeTab() === 'annotations' -->\n<div class=\"workbench-card-sidepanel-header-container\">\n    <h4 class=\"workbench-card-sidepanel-header\" data-bind=\"click: hideSidePanel\">\n        <span data-bind=\"text: \\$root.translations.annotationOverlays\"></span>\n    </h4>\n</div>\n<div class=\"workbench-card-sidepanel-border\"></div>\n<div class=\"workbench-card-sidepanel-body\">\n<div class=\"overlays-listing-container\" data-bind=\"sortable: {\n    data: annotationNodes\n}\">\n    <div class=\"overlay-listing\" data-bind=\"css: {'active-overlay': active}\">\n        <div class=\"overlay-name\" data-bind=\"\n            click: function() {\n                active(!active());\n            }\n        \">\n            <i data-bind=\"css: icon\" class=\"layer-listing-icon\"></i>\n            <span data-bind=\"text: name\"></span>\n        </div>\n        <div class=\"relative\">\n            <div class=\"overlay-opacity-control\">\n                <i class=\"fa fa-adjust\"></i>\n                <div class=\"overlay-opacity-slider\">\n                    <input type=\"range\" min=\"0\" max=\"100\" step=\"1\" data-bind=\"value: opacity, valueUpdate: 'input'\">\n                </div>\n            </div>\n        </div>\n    </div>\n</div>\n</div>\n<!--/ko -->\n\n\n    </div>\n    <!--/ko -->\n    <div class=\"workbench-card-container-wrapper\" data-bind=\"css: {\n        'workbench-card-container-sidepanel-active': activeTab(), 'wide': showTabs() === false\n    }\">\n    \n<!-- ko foreach: { data: [\\$data], as: 'self' } -->\n<!--ko if: ko.unwrap(self.mainMenu) -->\n\n\n<!--/ko-->\n<!--ko if: !ko.unwrap(self.mainMenu) -->\n<div class=\"workbench-card-container\" data-bind=\"css: {\n        'gallery-visible': showGallery,\n        'gallery-expanded': expandGallery\n    }\">\n\n    <div class=\"iiif-leaflet\" data-bind=\"leaflet: leafletConfig\">\n        <div class=\"split-controls left\" data-bind=\"if: secondaryCanvas\">\n            <div style=\"width: 200px\">\n                <select class=\"form-control input-lg widget-input\" data-bind=\"\n                    select2Query: {\n                        select2Config: leftSideSelectConfig\n                    }\">\n                </select>\n            </div>\n            <div class=\"button\" data-bind=\"click: imagePropertyUpdate.bind(\\$data,'left')\">\n                <i class=\"fa fa-picture-o\"></i>\n            </div>\n        </div>\n        <div class=\"split-controls right\" data-bind=\"if: secondaryCanvas\">\n            <div style=\"width: 200px;\">\n                <select class=\"form-control input-lg widget-input\" data-bind=\"\n                    select2Query: {\n                        select2Config: rightSideSelectConfig\n                    }\">\n                </select>\n            </div>\n            <div class=\"button\" data-bind=\"click: imagePropertyUpdate.bind(\\$data,'right')\">\n                <i class=\"fa fa-picture-o\"></i>\n            </div>\n        </div>\n    </div>\n    <div class=\"image-tools-floating\" data-bind=\"style: {display: showImageModifiers() ? 'inherit': 'none'}, css: {left: floatingLocation() == 'left', right: floatingLocation() == 'right', sidepanel: activeTab()}\">\n        <div class=\"iiif-image-tool-slider\">\n            <div class=\"iiif-image-tool-label\">\n                <i class=\"fa fa-lightbulb-o\"></i>\n                <span data-bind=\"text: \\$root.translations.brightness\"></span>\n            </div>\n            <div class=\"iiif-image-tool-slider-wrap\">\n                <input type=\"range\" min=\"0\" max=\"200\" step=\"1\" data-bind=\"value: brightness, valueUpdate: 'input'\">\n            </div>\n            <div class=\"iiif-image-tool-value\">\n                <span data-bind=\"text: brightness\"></span>%\n            </div>\n        </div>\n        <div class=\"iiif-image-tool-slider\">\n            <div class=\"iiif-image-tool-label\">\n                <i class=\"fa fa-adjust\"></i>\n                <span data-bind=\"text: \\$root.translations.contrast\"></span>\n            </div>\n            <div class=\"iiif-image-tool-slider-wrap\">\n                <input type=\"range\" min=\"0\" max=\"200\" step=\"1\" data-bind=\"value: contrast, valueUpdate: 'input'\">\n            </div>\n            <div class=\"iiif-image-tool-value\">\n                <span data-bind=\"text: contrast\"></span>%\n            </div>\n        </div>\n        <div class=\"iiif-image-tool-slider\">\n            <div class=\"iiif-image-tool-label\">\n                <i class=\"fa fa-eyedropper\"></i>\n                <span data-bind=\"text: \\$root.translations.saturation\"></span>\n            </div>\n            <div class=\"iiif-image-tool-slider-wrap\">\n                <input type=\"range\" min=\"0\" max=\"200\" step=\"1\" data-bind=\"value: saturation, valueUpdate: 'input'\">\n            </div>\n            <div class=\"iiif-image-tool-value\">\n                <span data-bind=\"text: saturation\"></span>%\n            </div>\n        </div>\n        <div class=\"iiif-image-tool-slider\">\n            <div class=\"iiif-image-tool-label\">\n                <i class=\"fa fa-image\"></i>\n                <span data-bind=\"text: \\$root.translations.greyscale\"></span>\n            </div>\n            <div class=\"toggle-container\">\n                <span class=\"switch switch-small switch-widget\" data-bind=\"css: {'on': greyscale()}, click: function() { greyscale(!greyscale()); }\"><small></small></span>\n                <div style=\"display:flex; flex-direction:row;\">\n                    <div class=\"arches-toggle-sm\" data-bind=\"click: function() { greyscale(!greyscale()); }\">\n                        <span data-bind=\"text: \\$root.translations.displayAsGreyscale\"></span>\n                    </div>\n                </div>\n            </div>\n        </div>\n    </div>\n</div>\n<div class=\"show-gallery-control\" data-bind=\"click: toggleGallery, css: {\n        'gallery-visible': showGallery,\n        'gallery-expanded': expandGallery,\n    }\">\n    <h3>\n        <span data-bind=\"text: \\$root.translations.showGallery\"></span>\n    </h3>\n</div>\n<!--ko let: {canvasClick: canvasClick, getCanvasService: getCanvasService, selectedCanvas: selectPrimaryPanel() ? canvas: secondaryCanvas, getAnnotationCount: getAnnotationCount} -->\n<div class=\"iiif-viewer-gallery\" data-bind=\"css: {\n        'gallery-expanded': expandGallery\n    }\">\n    <!--ko if: showGallery() -->\n    <div class=\"iiif-gallery-content\">\n\n        <!--ko if: manifestData() -->\n        <div class=\"panel-controls\">\n            <div class=\"hide-gallery-control\" data-bind=\"click: toggleGallery\">\n                <span data-bind=\"text: \\$root.translations.hideGallery\"></span>\n            </div>\n            <div data-bind=\"if: showModeSelector\" class=\"mode-selector\">\n                <div>\n                    <span data-bind=\"text: \\$root.translations.panels\"></span>\n                </div>\n                <div class=\"mode-selector-buttons\">\n                    <div class=\"single-panel\" data-bind=\"click: function(){compareMode(false)}, css: {selected: !compareMode()}\">\n                        <div></div>\n                    </div>\n                    <div class=\"two-panel\" data-bind=\"click: function(){compareMode(true)}, css: {selected: compareMode()}\">\n                        <div></div>\n                        <div></div>\n                    </div>\n                </div>\n                <div class=\"panel-selector-buttons\">\n                    <div data-bind=\"click: function(){selectPrimaryPanel(true)}, css: { selected: selectPrimaryPanel() }\">\n                        <span data-bind=\"text: \\$root.translations.panelOne\"></span>\n                    </div>\n                    <div data-bind=\"click: function(){selectPrimaryPanel(false)}, css: { selected: !selectPrimaryPanel(), hide: !compareMode() }\">\n                        <span data-bind=\"text: \\$root.translations.panelTwo\"></span>\n                    </div>\n                </div>\n            </div>\n        </div>\n        <!--/ko -->\n        <!--ko if: expandGallery() && manifestData() -->\n        <div class=\"manifest-details\">\n            <h3>\n                <span data-bind=\"text: manifestName\"></span>\n            </h3>\n\n            <h4>\n                <span data-bind=\"html: manifestDescription\"></span>\n            </h4>\n\n            <div class=\"manifest-details-list\" data-bind=\"foreach: manifestMetadata\">\n                <dt class=\"manifest-metadata-title\" data-bind=\"text: label\"></dt>\n                <!--ko foreach: Array.isArray(value) ? value : [value] -->\n                <dd class=\"manifest-metadata-value\" data-bind=\"html: \\$data\"></dd>\n                <!--/ko -->\n            </div>\n            <h4 class=\"manifest-attribution-key\" data-bind=\"html: manifestAttribution\"></h4>\n            <!-- ko if: showLogo -->\n            <img class=\"manifest-logo\" data-bind=\"attr: {src: manifestLogo()}\">\n            <!-- /ko -->\n        </div>\n        <!--/ko -->\n\n        <!--ko if: editManifest() -->\n        <div class=\"manifest-editor\">\n            <div class=\"manifest-editor-label\">\n                <span data-bind=\"text: \\$root.translations.selectAManifest + ':'\"></span>\n            </div>\n            <div class=\"manifest-editor-input\">\n                <select class=\"form-control input-lg widget-input\" data-bind=\"select2Query: {\n                        select2Config: manifestSelectConfig\n                    }\">\n                </select>\n            </div>\n\n            <div class=\"install-buttons\">\n                <button class=\"btn btn-shim btn-mint btn-labeled btn-lg fa fa-pencil\" data-bind=\"click: getManifestData,\n                    disabled: manifestLoading(),\n                    css: { 'disabled': manifestLoading() }\n                \">\n                    <span data-bind=\"text: \\$root.translations.loadManifest\"></span>\n                </button>\n                <!--ko if: manifestData() -->\n                <button class=\"btn btn-shim btn-danger btn-labeled btn-lg fa fa-refresh\" data-bind=\"click: toggleManifestEditor\">\n                    <span data-bind=\"text: \\$root.translations.cancel\"></span>\n                </button>\n                <!--/ko -->\n                <!--ko if: manifestLoading() -->\n                <span class=\"manifest-editor-loading\" data-bind=\"text: \\$root.translations.loadingManifest + '...'\"></span>\n                <!--/ko -->\n                <!--ko if: manifestError() -->\n                <span data-bind=\"text: console.log(manifestError())\"></span>\n                <span class=\"manifest-editor-error\" data-bind=\"text: \\$root.translations.errorLoadingManifest + '...'\"></span>\n                <!--/ko -->\n            </div>\n        </div>\n\n\n        <!--/ko -->\n        <!--ko if: !editManifest() -->\n            <!--ko if: manifestLoading() -->\n            <span class=\"manifest-editor-loading\" data-bind=\"text: \\$root.translations.loadingManifest + '...'\"></span>\n            <!--/ko -->\n            <!--ko if: !manifestLoading() -->\n            <div class=\"iiif-gallery-panel\" style=\"overflow-x: auto;\">\n                <div class=\"iiif-gallery-header\" style=\"display:flex\">\n                    <div style=\"display: flex; align-items: center\">\n                        \n                        <div>\n                            <span class=\"iiif-gallery-manifest-label\" data-bind=\"text: manifestData() ? manifestName() : \\$root.translations.noManifestSelected\"></span>\n                        </div>\n                        <div>\n                            <span class=\"iiif-gallery-sequence-label\" data-bind=\"click: function(){expandGallery(!expandGallery())}\">\n                                <!-- ko if: !expandGallery() -->\n                                    <span data-bind=\"text: \\$root.translations.info\"></span>\n                                <!-- /ko -->\n                                <!-- ko if: expandGallery() -->\n                                    <span data-bind=\"text: \\$root.translations.close\"></span>\n                                <!-- /ko -->\n                            </span>\n                        </div>\n                        <div>\n                            <span class=\"iiif-gallery-sequence-label\" data-bind=\"\n                                    text: \\$root.translations.switchImageService,\n                                    click: toggleManifestEditor\n                                \"></span>\n                        </div>\n                        <div class=\"iiif-list-filter\">\n                            <span data-bind=\"text: \\$root.translations.filter\"></span>\n                            <div class=\"list-filter\">\n                                <input type=\"text\" class=\"form-control\" style=\"width: 100%;\" data-bind=\"\n                                        textInput: filter,\n                                        attr: {placeholder: \\$root.translations.filterImages + '...'}\n                                    \">\n                                <!-- Clear Search -->\n                                <span class=\"clear-node-search\" data-bind=\"visible: filter().length > 0, click: function() { filter(''); }\"><i class=\"fa fa-times-circle\"></i></span>\n                            </div>\n                        </div>\n                        \n                    </div>\n                </div>\n\n                <div class=\"iiif-gallery-sequence\">\n                    <div class=\"iiif-gallery-sequence-canvases\" data-bind=\"foreach: canvases\">\n                        <div style=\"display: inline-block;\">\n                            <div class=\"iiif-gallery-canvas\" data-bind=\"click: function() {\n                                canvasClick(\\$data);\n                            },\n                            visible: label.toLowerCase().includes(self.filter().toLowerCase()),\n                            css: {\n                                active: getCanvasService(\\$data) === selectedCanvas(),\n                                annotated: getAnnotationCount(getCanvasService(\\$data))\n                            }\">\n                                <div style=\"text-align:center\" class=\"iiif-gallery-canvas-thumbnail\">\n                                    <img data-bind=\"attr: { src: \\$data.thumbnail || '/static/img/photo_missing.png', title: \\$data.label}\">\n                                </div>\n                                <div style=\"text-align:center;\" class=\"iiif-gallery-canvas-label\">\n                                    <span data-bind=\"text: label\"></span>\n                                    <span class=\"annotation-count\">\n                                        <!--ko if: getAnnotationCount(getCanvasService(\\$data)) -->\n                                        <span data-bind=\"text: getAnnotationCount(getCanvasService(\\$data))\"></span>\n                                        <span data-bind=\"text: \\$root.translations.annotations\"></span>\n                                        <!--/ko -->\n                                        <!--ko if: !getAnnotationCount(getCanvasService(\\$data)) -->\n                                        &nbsp;\n                                        <!--/ko -->\n                                    </span>\n                                </div>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n            </div>\n            <!--/ko -->\n        <!--/ko -->\n    </div>\n    <!--/ko -->\n</div>\n<!--/ko -->\n<!--/ko -->\n<!--/ko -->\n\n</div>\n</div>\n\n<!-- /ko -->\n\n`;\n// Exports\nmodule.exports = code;\n\n//# sourceURL=webpack://afs_plocal/../arches-for-science/arches_for_science/templates/views/components/workflows/upload-dataset/select-dataset-files-step.htm?\n}");

